//! 🧪️ A real original issuer and fixed qualified stamp select one registered admission source without key traversal.
use super::*;
use semio_framework_value::retained_clone::RetainedCloneSource;
struct Qualified(ChildAdmissionStamp);
impl ChildAdmissionQualificationV1 for Qualified{fn child_admission_stamp(&self)->ChildAdmissionStamp{self.0}}
struct Registered;
static REGISTERED:Registered=Registered;
impl EmbeddedChildAdmitterV1 for Registered{fn birth_demand(&self)->RetirementDemand{Default::default()}fn begin(&self,_:RetainedCloneGrant)->Result<(EmbeddedChildAdmission,RetainedCloneProgress),ValueError>{Err(refusal("test producer is selected but never constructed"))}}
impl semio_framework_io_ports::EmbeddedChildVectorSourceV1 for Registered{fn read_demand(&self)->RetirementDemand{Default::default()}fn read<'a>(&self,_:semio_framework_io_ports::ChildAdmissionSource<'a>,_:RetainedCloneGrant)->Result<semio_framework_io_ports::VectorGraphAdvance<'a>,ValueError>{Err(refusal("test vector selected but never polled"))}}
struct Provider{stamp:Qualified,source:RetainedCloneSource<usize>}
impl ChildAdmissionProviderV1 for Provider{fn read(&self,address:ChildAdmissionAddress)->Result<ChildAdmissionRead<'_>,ValueError>{if address.ordinal()!=3||!address.matches(&self.stamp){return Err(refusal("foreign original prepared child address"))}Ok(ChildAdmissionRead{source:erase_child_admission_source(self.source.borrow(),0x4348494c),admitter:&REGISTERED,vector:&REGISTERED})}}
#[test]
fn original_fixed_qualified_provider_address_refuses_every_substitution(){let fixture:serde_json::Value=serde_json::from_str(include_str!("🧪️.json")).unwrap();assert_eq!(fixture["fields"].as_array().unwrap().len(),7);let g=RetainedCloneGrant{maximum_items:8,maximum_copy_bytes:8192,maximum_capacity_bytes:8192,maximum_release_bytes:8192,maximum_depth:4};let stamp=Qualified(ChildAdmissionStamp{parent_identity:11,expected_reference_identity:22,child_identity:33,capability_identity:44,request_identity:55,parent_revision:[7;32],child_revision:[9;32]});assert!(ChildAdmissionAddress::admit(3,&stamp,Default::default()).is_err());let(address,p)=ChildAdmissionAddress::admit(3,&stamp,g).unwrap();assert!(p.fits(g));assert_eq!(p.retained_capacity_bytes,0);assert!(address.matches(&stamp));let(source,_)=RetainedCloneSource::admit_owned(7usize,(),g).unwrap_or_else(|_|panic!("actual original issuer"));let mut provider=Provider{stamp,source};{let read=provider.read(address).unwrap();assert_eq!(read.source.get().downcast_ref::<usize>(),Some(&7));assert!(std::ptr::eq(read.admitter,&REGISTERED as &dyn EmbeddedChildAdmitterV1));}assert!(std::ptr::eq(provider.read(address).unwrap().vector,&REGISTERED as &dyn semio_framework_io_ports::EmbeddedChildVectorSourceV1));for field in 0..7{let mut other=provider.stamp.0;match field{0=>other.parent_identity+=1,1=>other.expected_reference_identity+=1,2=>other.child_identity+=1,3=>other.capability_identity+=1,4=>other.request_identity+=1,5=>other.parent_revision[31]+=1,_=>other.child_revision[31]+=1}assert!(!address.matches(&Qualified(other)));let foreign=ChildAdmissionAddress::admit(3,&Qualified(other),g).unwrap().0;assert!(provider.read(foreign).is_err());}for ordinal in [0,2,4]{assert!(provider.read(ChildAdmissionAddress::admit(ordinal,&provider.stamp,g).unwrap().0).is_err());}while !provider.source.terminal_is_empty(){provider.source.close_step(g).unwrap();}}
